export type PopArtMood = 'Classic Pop Art' | 'Funny/Caricature' | 'Emotional/Dramatic' | 'Retro Comic';

export interface PopArtConfig {
  mood: PopArtMood;
  coupleName?: string;
  customText?: string;
}

export interface TransformationResult {
  imageUrl: string;
  originalUrl: string;
  timestamp: number;
}

import { GoogleGenAI } from "@google/genai";
import { PopArtConfig } from "../types";

export const transformToPopArt = async (
  base64Image: string,
  mimeType: string,
  config: PopArtConfig
): Promise<string> => {
  // Initialize AI right before call to use current API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Transform this uploaded image into a professional ${config.mood} style Pop Art illustration.

    CRITICAL VISUAL STYLE RULES:
    - Apply bold, thick black comic ink outlines to all subjects.
    - Use clean vector-style edges and flat pop-art color fills (Cyan, Magenta, Yellow, Black palettes).
    - Incorporate heavy halftone dot shading (Ben-Day dots) on skin tones, clothing, and background areas.
    - BACKGROUND: Replace the current background with a dynamic radial burst or "Kirby Krackle" comic effect with high-energy speed lines.
    - NO Photorealism: The result must look like a hand-drawn vintage printed comic book from the 1960s.

    TEXT OVERLAY INSTRUCTIONS:
    ${config.coupleName ? `- Stylistically render the names "${config.coupleName}" in a rectangular "caption box" or a vibrant corner banner.` : ''}
    ${config.customText ? `- Add a comic speech bubble or an action-oriented "caption box" containing the text: "${config.customText}".` : ''}

    Ensure all text is legible, spelled correctly, and integrated into the comic aesthetic.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1] || base64Image, // Strip data URL prefix if present
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    let generatedImageUrl = '';

    // Iterate through candidates and parts to find the image part
    if (response.candidates && response.candidates[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          generatedImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!generatedImageUrl) {
      throw new Error("No image data returned from the model. Try a different mood or image.");
    }

    return generatedImageUrl;
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Failed to generate Pop Art. Please check your API key and connection.");
  }
};

