import React, { useState, useCallback, useRef } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: PopArtMood[] = [
  'Classic Pop Art',
  'Funny/Caricature',
  'Emotional/Dramatic',
  'Retro Comic'
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [loadingMsgIndex, setLoadingMsgIndex] = useState(0);

  const loadingMessages = [
    "Applying halftone dots...",
    "Ink-washing the edges...",
    "Igniting the Kirby Krackle...",
    "Printing the vector layers...",
    "Finalizing the 1960s aesthetic...",
    "Checking the ink registration..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null); // Clear previous result
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);

    // Rotation of loading messages
    const msgInterval = setInterval(() => {
      setLoadingMsgIndex(prev => (prev + 1) % loadingMessages.length);
    }, 2500);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      setResult({
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      });
    } catch (err: any) {
      setError(err.message);
    } finally {
      clearInterval(msgInterval);
      setLoading(false);
    }
  };

  const handleDownload = () => {
    if (!result) return;
    const link = document.createElement('a');
    link.href = result.imageUrl;
    link.download = `pop-art-${Date.now()}.png`;
    link.click();
  };

  return (
    <Layout>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Sidebar Controls */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white pop-art-border p-6 pop-art-shadow">
            <h2 className="text-2xl font-comic mb-4 uppercase text-red-500 border-b-2 border-black pb-2">
              <i className="fas fa-cog mr-2"></i> Settings
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold uppercase mb-1">Pick Your Style</label>
                <div className="grid grid-cols-2 gap-2">
                  {MOODS.map(mood => (
                    <button
                      key={mood}
                      onClick={() => setConfig({ ...config, mood })}
                      className={`text-sm py-2 px-1 border-2 font-bold transition-all ${
                        config.mood === mood 
                          ? 'bg-blue-600 text-white border-black scale-105' 
                          : 'bg-gray-100 border-gray-300 hover:border-black'
                      }`}
                    >
                      {mood}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold uppercase mb-1">Upload Photo</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="pop-art-border border-dashed p-8 bg-blue-50 cursor-pointer hover:bg-blue-100 transition-colors text-center"
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*" 
                    onChange={handleFileChange}
                  />
                  <i className="fas fa-cloud-upload-alt text-3xl mb-2 text-blue-600"></i>
                  <p className="text-xs font-bold uppercase">Click or Drag Image Here</p>
                  {file && <p className="text-xs text-green-600 mt-2 font-bold">{file.name}</p>}
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold uppercase mb-1">Names (Optional)</label>
                <input 
                  type="text"
                  placeholder="e.g. Ayush & Rutvi"
                  value={config.coupleName}
                  onChange={(e) => setConfig({ ...config, coupleName: e.target.value })}
                  className="w-full pop-art-border p-2 text-sm focus:outline-none focus:bg-yellow-50"
                />
              </div>

              <div>
                <label className="block text-sm font-bold uppercase mb-1">Message (Optional)</label>
                <textarea 
                  placeholder="e.g. Happy Anniversary!"
                  value={config.customText}
                  onChange={(e) => setConfig({ ...config, customText: e.target.value })}
                  rows={2}
                  className="w-full pop-art-border p-2 text-sm focus:outline-none focus:bg-yellow-50 resize-none"
                />
              </div>

              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-2xl py-4 uppercase transition-all flex items-center justify-center gap-2 ${
                  !file || loading 
                    ? 'bg-gray-300 cursor-not-allowed border-gray-400 text-gray-500' 
                    : 'bg-red-500 hover:bg-red-600 text-white pop-art-border hover:-translate-y-1 hover:translate-x-1 hover:shadow-lg'
                }`}
              >
                {loading ? (
                  <><i className="fas fa-spinner fa-spin"></i> ZAPPING...</>
                ) : (
                  <><i className="fas fa-bolt"></i> Transform Now!</>
                )}
              </button>
            </div>
          </div>

          {error && (
            <div className="bg-red-100 border-l-8 border-red-600 p-4 font-bold text-red-800 animate-pulse">
              <i className="fas fa-exclamation-triangle mr-2"></i> ERROR: {error}
            </div>
          )}
        </div>

        {/* Main Display Area */}
        <div className="lg:col-span-8 space-y-8">
          {loading && (
            <div className="bg-white pop-art-border p-12 text-center space-y-6 flex flex-col items-center justify-center min-h-[500px]">
              <div className="relative">
                <div className="w-24 h-24 border-8 border-blue-600 border-t-red-500 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <i className="fas fa-atom text-yellow-400 text-2xl animate-ping"></i>
                </div>
              </div>
              <h3 className="text-4xl font-comic text-blue-600 animate-bounce">{loadingMessages[loadingMsgIndex]}</h3>
              <p className="font-comic text-xl text-gray-500 italic max-w-md">Our AI comic artists are hand-inking your masterpiece with pixel-perfect precision!</p>
            </div>
          )}

          {!loading && !result && (
            <div className="bg-white pop-art-border p-12 text-center space-y-6 flex flex-col items-center justify-center min-h-[500px] border-dashed">
              {!previewUrl ? (
                <>
                  <div className="bg-yellow-400 pop-art-border p-6 rounded-full rotate-3 mb-4">
                    <i className="fas fa-image text-5xl text-black"></i>
                  </div>
                  <h3 className="text-4xl font-comic">Upload to Start the Magic!</h3>
                  <p className="font-comic text-xl text-gray-500 max-w-md">Your original photo will appear here before we zap it into a comic icon.</p>
                </>
              ) : (
                <div className="w-full">
                  <h3 className="text-3xl font-comic mb-4 text-left">Preview:</h3>
                  <div className="relative inline-block pop-art-border pop-art-shadow">
                    <img src={previewUrl} alt="Preview" className="max-h-[600px] w-auto block" />
                    <div className="absolute top-4 left-4 bg-yellow-400 px-3 py-1 font-comic text-xl pop-art-border rotate-[-5deg]">ORIGINAL</div>
                  </div>
                </div>
              )}
            </div>
          )}

          {result && !loading && (
            <div className="space-y-6 animate-fadeIn">
              <div className="flex items-center justify-between">
                <h3 className="text-4xl font-comic uppercase text-blue-600">Masterpiece Ready!</h3>
                <div className="flex gap-4">
                  <button 
                    onClick={() => setResult(null)} 
                    className="bg-gray-200 pop-art-border px-4 py-2 font-comic text-xl uppercase hover:bg-gray-300"
                  >
                    Reset
                  </button>
                  <button 
                    onClick={handleDownload} 
                    className="bg-green-500 text-white pop-art-border px-6 py-2 font-comic text-xl uppercase hover:bg-green-600 pop-art-shadow"
                  >
                    <i className="fas fa-download mr-2"></i> Save Art
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <p className="font-comic text-gray-500 uppercase">Your Input</p>
                  <div className="pop-art-border opacity-70 grayscale hover:grayscale-0 transition-all">
                    <img src={result.originalUrl} alt="Original" className="w-full h-[400px] object-cover" />
                  </div>
                </div>
                <div className="space-y-2">
                  <p className="font-comic text-red-500 uppercase">Comic Result</p>
                  <div className="pop-art-border pop-art-shadow relative overflow-hidden group">
                    <img src={result.imageUrl} alt="Result" className="w-full h-[400px] object-cover" />
                    <div className="absolute inset-0 bg-blue-600 opacity-0 group-hover:opacity-10 transition-opacity pointer-events-none"></div>
                  </div>
                </div>
              </div>

              <div className="bg-white pop-art-border p-6 pop-art-shadow mt-8">
                <div className="flex items-start gap-4">
                  <div className="bg-red-500 text-white rounded-full p-3 pop-art-border">
                    <i className="fas fa-info-circle text-2xl"></i>
                  </div>
                  <div>
                    <h4 className="font-comic text-2xl uppercase">Pro Tip!</h4>
                    <p className="text-gray-600 font-medium">For best results with text, ensure your "Names" and "Message" aren't too long. The AI comic engine loves short, punchy phrases!</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default App;

export type PopArtMood = 'Classic Pop Art' | 'Funny/Caricature' | 'Emotional/Dramatic' | 'Retro Comic' | 'Futuristic Pop';

export interface PopArtConfig {
  mood: PopArtMood;
  coupleName?: string;
  customText?: string;
}

export interface TransformationResult {
  imageUrl: string;
  originalUrl: string;
  timestamp: number;
}

import { GoogleGenAI } from "@google/genai";
import { PopArtConfig } from "../types";

export const transformToPopArt = async (
  base64Image: string,
  mimeType: string,
  config: PopArtConfig
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let styleSpecifics = '';
  if (config.mood === 'Futuristic Pop') {
    styleSpecifics = `
      - Use a Neon-Cyberpunk color palette (Neon Pink, Electric Blue, Acid Green).
      - Add subtle holographic textures and glowing circuit-board patterns in the background.
      - Subjects should have glowing neon outlines in addition to thick black ink.
      - Incorporate digital glitch effects or geometric synthwave suns in the backdrop.
    `;
  } else {
    styleSpecifics = `- Use clean vector-style edges and flat pop-art color fills (Cyan, Magenta, Yellow, Black palettes).`;
  }

  const prompt = `
    Transform this uploaded image into a professional ${config.mood} style illustration.

    CRITICAL VISUAL STYLE RULES:
    - Apply bold, thick black comic ink outlines to all subjects.
    ${styleSpecifics}
    - Incorporate heavy halftone dot shading (Ben-Day dots) on skin tones, clothing, and background areas.
    - BACKGROUND: Replace the current background with a dynamic radial burst, "Kirby Krackle", or high-energy speed lines.
    - NO Photorealism: The result must look like a stylized piece of art.

    TEXT OVERLAY INSTRUCTIONS:
    ${config.coupleName ? `- Stylistically render the names "${config.coupleName}" in a rectangular "caption box" or a vibrant corner banner.` : ''}
    ${config.customText ? `- Add a comic speech bubble or an action-oriented "caption box" containing the text: "${config.customText}".` : ''}

    Ensure all text is legible, spelled correctly, and integrated into the aesthetic.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1] || base64Image,
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    let generatedImageUrl = '';
    if (response.candidates && response.candidates[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          generatedImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!generatedImageUrl) {
      throw new Error("No image data returned from the model. Try a different mood or image.");
    }

    return generatedImageUrl;
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Failed to generate art. Please check your API key and connection.");
  }
};

import React, { useState, useRef } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: { label: PopArtMood; icon: string; color: string }[] = [
  { label: 'Classic Pop Art', icon: 'fa-palette', color: 'bg-yellow-400' },
  { label: 'Retro Comic', icon: 'fa-book-open', color: 'bg-blue-400' },
  { label: 'Futuristic Pop', icon: 'fa-rocket', color: 'bg-purple-500' },
  { label: 'Funny/Caricature', icon: 'fa-laugh-wink', color: 'bg-green-400' },
  { label: 'Emotional/Dramatic', icon: 'fa-heart', color: 'bg-red-400' }
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [history, setHistory] = useState<TransformationResult[]>([]);
  const [loadingMsgIndex, setLoadingMsgIndex] = useState(0);

  const loadingMessages = [
    "Analyzing visual structure...",
    "Injecting neon energy...",
    "Processing halftone matrices...",
    "Drafting bold ink contours...",
    "Rendering holographic layers...",
    "Calibrating comic aesthetics..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);

    const msgInterval = setInterval(() => {
      setLoadingMsgIndex(prev => (prev + 1) % loadingMessages.length);
    }, 2000);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      const newResult = {
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      };
      setResult(newResult);
      setHistory(prev => [newResult, ...prev].slice(0, 10)); // Keep last 10
    } catch (err: any) {
      setError(err.message);
    } finally {
      clearInterval(msgInterval);
      setLoading(false);
    }
  };

  const handleDownload = (url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `pop-art-${Date.now()}.png`;
    link.click();
  };

  return (
    <Layout>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* SIDEBAR: CONTROLS */}
        <div className="lg:col-span-4 space-y-6 lg:sticky lg:top-24">
          <div className="bg-white pop-art-border p-6 pop-art-shadow transform rotate-1">
            <h2 className="text-3xl font-comic mb-4 uppercase text-black border-b-4 border-black pb-2 flex justify-between items-center">
              <span>Controls</span>
              <i className="fas fa-sliders-h text-red-500"></i>
            </h2>

            <div className="space-y-5">
              {/* Mood Selection */}
              <div>
                <label className="block text-xs font-black uppercase mb-2 tracking-widest text-gray-500">1. Select Art Style</label>
                <div className="flex flex-wrap gap-2">
                  {MOODS.map(m => (
                    <button
                      key={m.label}
                      onClick={() => setConfig({ ...config, mood: m.label })}
                      className={`flex items-center gap-2 text-xs py-2 px-3 border-2 font-black uppercase transition-all shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] active:translate-x-[1px] active:translate-y-[1px] active:shadow-none ${
                        config.mood === m.label 
                          ? `${m.color} text-black border-black scale-105 z-10` 
                          : 'bg-white border-gray-300 hover:border-black text-gray-600'
                      }`}
                    >
                      <i className={`fas ${m.icon}`}></i>
                      {m.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Upload */}
              <div>
                <label className="block text-xs font-black uppercase mb-2 tracking-widest text-gray-500">2. Source Material</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`pop-art-border border-dashed p-6 cursor-pointer transition-all text-center relative overflow-hidden group ${file ? 'bg-green-50' : 'bg-gray-50 hover:bg-yellow-50'}`}
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*" 
                    onChange={handleFileChange}
                  />
                  <div className="relative z-10">
                    <i className={`fas ${file ? 'fa-check-circle text-green-500' : 'fa-camera-retro text-black'} text-4xl mb-2 group-hover:scale-110 transition-transform`}></i>
                    <p className="text-sm font-black uppercase">{file ? 'Photo Loaded!' : 'Snap or Upload'}</p>
                    {file && <p className="text-[10px] text-gray-600 mt-1 truncate max-w-full px-2">{file.name}</p>}
                  </div>
                  <div className="absolute inset-0 opacity-10 bg-[radial-gradient(circle,black_1px,transparent_1px)] bg-[size:10px_10px]"></div>
                </div>
              </div>

              {/* Fields */}
              <div className="space-y-3">
                <label className="block text-xs font-black uppercase tracking-widest text-gray-500">3. Personalization</label>
                <div className="relative">
                  <span className="absolute left-3 top-2 text-red-500 font-black">#</span>
                  <input 
                    type="text"
                    placeholder="NAME (OPTIONAL)"
                    value={config.coupleName}
                    onChange={(e) => setConfig({ ...config, coupleName: e.target.value })}
                    className="w-full pop-art-border pl-8 p-2 text-xs font-bold uppercase focus:outline-none focus:bg-yellow-100 placeholder:text-gray-300"
                  />
                </div>
                <div className="relative">
                  <span className="absolute left-3 top-2 text-blue-500 font-black">@</span>
                  <textarea 
                    placeholder="MESSAGE (OPTIONAL)"
                    value={config.customText}
                    onChange={(e) => setConfig({ ...config, customText: e.target.value })}
                    rows={2}
                    className="w-full pop-art-border pl-8 p-2 text-xs font-bold uppercase focus:outline-none focus:bg-yellow-100 placeholder:text-gray-300 resize-none"
                  />
                </div>
              </div>

              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-3xl py-4 uppercase transition-all flex items-center justify-center gap-3 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] active:shadow-none active:translate-x-[4px] active:translate-y-[4px] border-4 border-black ${
                  !file || loading 
                    ? 'bg-gray-200 cursor-not-allowed text-gray-400 border-gray-400 shadow-none' 
                    : 'bg-red-500 hover:bg-red-600 text-white'
                }`}
              >
                {loading ? (
                  <><i className="fas fa-circle-notch fa-spin"></i> ZAPPING...</>
                ) : (
                  <><i className="fas fa-bolt"></i> GO ART!</>
                )}
              </button>
            </div>
          </div>

          {error && (
            <div className="bg-white border-4 border-black p-4 font-black uppercase text-red-600 text-xs shadow-[4px_4px_0px_0px_rgba(220,38,38,1)]">
              <i className="fas fa-bomb mr-2 animate-bounce"></i> ERROR: {error}
            </div>
          )}

          {/* HISTORY SECTION */}
          {history.length > 0 && (
            <div className="bg-white pop-art-border p-4 shadow-md transform -rotate-1">
              <h3 className="font-comic text-xl uppercase mb-3 border-b-2 border-black">History Box</h3>
              <div className="grid grid-cols-4 gap-2">
                {history.map((h, i) => (
                  <button 
                    key={i} 
                    onClick={() => setResult(h)}
                    className="border-2 border-black hover:scale-110 transition-transform bg-gray-100 h-16 overflow-hidden"
                  >
                    <img src={h.imageUrl} alt="prev" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* MAIN CANVAS */}
        <div className="lg:col-span-8 space-y-8">
          {loading && (
            <div className="bg-white pop-art-border p-12 text-center space-y-8 flex flex-col items-center justify-center min-h-[600px] relative overflow-hidden">
              <div className="absolute inset-0 opacity-5 bg-[linear-gradient(45deg,#000_25%,transparent_25%,transparent_50%,#000_50%,#000_75%,transparent_75%,transparent)] bg-[size:40px_40px] animate-[pulse_2s_infinite]"></div>

              <div className="relative z-10 flex flex-col items-center">
                <div className="w-32 h-32 relative mb-8">
                  <div className="absolute inset-0 border-8 border-black border-t-transparent rounded-full animate-spin"></div>
                  <div className="absolute inset-4 border-8 border-red-500 border-b-transparent rounded-full animate-[spin_1.5s_linear_infinite_reverse]"></div>
                  <div className="absolute inset-8 bg-black rounded-full flex items-center justify-center">
                    <i className="fas fa-star text-yellow-400 text-2xl animate-ping"></i>
                  </div>
                </div>

                <h3 className="text-5xl font-comic text-black uppercase tracking-tighter drop-shadow-lg animate-bounce">
                  {loadingMessages[loadingMsgIndex]}
                </h3>
                <p className="font-comic text-2xl text-blue-600 uppercase italic mt-4 max-w-lg">
                  Hang tight! Our mechanical pencils are sharp and our neon inks are ready!
                </p>
              </div>
            </div>
          )}

          {!loading && !result && (
            <div className={`bg-white pop-art-border p-12 text-center min-h-[600px] flex flex-col items-center justify-center border-dashed transition-all ${previewUrl ? 'border-solid' : 'border-gray-300'}`}>
              {!previewUrl ? (
                <div className="group">
                  <div className="bg-yellow-400 pop-art-border p-8 rounded-full inline-block group-hover:rotate-12 transition-transform shadow-[8px_8px_0px_0px_rgba(0,0,0,1)]">
                    <i className="fas fa-image text-7xl text-black"></i>
                  </div>
                  <h3 className="text-5xl font-comic mt-8 uppercase tracking-tighter">Your Masterpiece Starts Here!</h3>
                  <p className="font-comic text-2xl text-gray-500 max-w-md mx-auto mt-4">Feed the AI a photo and watch the magic unfold in high-vibrant pixels!</p>
                </div>
              ) : (
                <div className="w-full space-y-6">
                  <div className="flex justify-between items-center">
                    <h3 className="text-4xl font-comic uppercase">Preview Ready!</h3>
                    <button onClick={() => setFile(null) || setPreviewUrl(null)} className="text-red-500 font-black uppercase text-sm border-b-2 border-red-500 pb-0.5">Change Photo</button>
                  </div>
                  <div className="inline-block relative pop-art-border shadow-[12px_12px_0px_0px_rgba(0,0,0,1)] overflow-hidden">
                    <img src={previewUrl} alt="Preview" className="max-h-[550px] w-auto block grayscale hover:grayscale-0 transition-all duration-500 cursor-crosshair" />
                    <div className="absolute top-4 left-4 bg-black text-white px-4 py-1 font-comic text-2xl -rotate-2">SOURCE</div>
                    <div className="absolute bottom-4 right-4 bg-yellow-400 border-2 border-black text-black px-4 py-1 font-comic text-xl rotate-1">PENDING ZAP...</div>
                  </div>
                </div>
              )}
            </div>
          )}

          {result && !loading && (
            <div className="space-y-8 animate-[fadeIn_0.5s_ease-out]">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h3 className="text-5xl font-comic uppercase text-black italic tracking-tighter">
                  <span className="bg-blue-600 text-white px-2 mr-2">POW!</span> {config.mood} Ready
                </h3>
                <div className="flex gap-4">
                  <button 
                    onClick={() => handleDownload(result.imageUrl)} 
                    className="bg-green-500 text-white border-4 border-black px-8 py-3 font-comic text-2xl uppercase hover:bg-green-600 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] active:shadow-none active:translate-x-[2px] active:translate-y-[2px]"
                  >
                    <i className="fas fa-save mr-2"></i> Save Art
                  </button>
                </div>
              </div>

              <div className="bg-white pop-art-border p-4 shadow-[15px_15px_0px_0px_rgba(59,130,246,0.3)] group">
                <div className="relative overflow-hidden cursor-zoom-in">
                  <img src={result.imageUrl} alt="Result" className="w-full max-h-[800px] object-contain block transform transition-transform duration-700 group-hover:scale-[1.02]" />
                  <div className="absolute top-6 left-6 bg-red-500 text-white px-6 py-2 font-comic text-3xl pop-art-border -rotate-3 uppercase shadow-lg">FINAL ART</div>

                  {/* Floating Action Badge */}
                  <div className="absolute bottom-6 left-6 bg-yellow-400 border-4 border-black px-4 py-2 font-comic text-xl rotate-3 flex items-center gap-2">
                    <i className="fas fa-check-double"></i> Verified Comic
                  </div>
                </div>
              </div>

              {/* Comparison Section */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-center">
                 <div className="bg-white pop-art-border p-4 opacity-70 hover:opacity-100 transition-opacity">
                    <p className="font-comic text-lg uppercase mb-2 text-gray-500">Original Reference</p>
                    <img src={result.originalUrl} alt="Orig" className="w-full h-48 object-cover border-2 border-black" />
                 </div>
                 <div className="bg-black text-white p-6 pop-art-border rotate-1">
                    <h4 className="font-comic text-2xl mb-2 text-yellow-400">Share the Vibes!</h4>
                    <p className="text-sm font-bold uppercase mb-4 opacity-80 italic">This masterpiece is unique. Print it, frame it, or make it your pfp!</p>
                    <div className="flex gap-4">
                      <button className="flex-1 bg-white text-black py-2 font-black uppercase text-xs hover:bg-gray-200 transition-colors">Copy URL</button>
                      <button className="flex-1 bg-blue-500 text-white py-2 font-black uppercase text-xs hover:bg-blue-600 transition-colors">Tweet Art</button>
                    </div>
                 </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* GLOBAL ANIMATIONS */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: { label: PopArtMood; icon: string; color: string; desc: string }[] = [
  { label: 'Classic Pop Art', icon: 'fa-palette', color: 'bg-yellow-400', desc: 'Lichtenstein-inspired dots and primary colors.' },
  { label: 'Futuristic Pop', icon: 'fa-user-astronaut', color: 'bg-purple-600', desc: 'Neon glows, holographic grids, and cyberpunk flair.' },
  { label: 'Retro Comic', icon: 'fa-book-open', color: 'bg-blue-500', desc: '1960s silver age comic book style.' },
  { label: 'Funny/Caricature', icon: 'fa-laugh-squint', color: 'bg-green-500', desc: 'Exaggerated features and wacky colors.' },
  { label: 'Emotional/Dramatic', icon: 'fa-bolt', color: 'bg-red-500', desc: 'High contrast noir-meets-color drama.' }
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [history, setHistory] = useState<TransformationResult[]>([]);
  const [loadingMsg, setLoadingMsg] = useState("");

  const loadingMessages = [
    "Analyzing visual structure...",
    "Injecting halftone energy...",
    "Sharpening ink contours...",
    "Applying vector registration...",
    "Finalizing comic aesthetic..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (loading) {
      let i = 0;
      const interval = setInterval(() => {
        setLoadingMsg(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);
    setLoadingMsg(loadingMessages[0]);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      const newResult = {
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      };
      setResult(newResult);
      setHistory(prev => [newResult, ...prev].slice(0, 5));
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = (url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `pop-magic-${Date.now()}.png`;
    link.click();
  };

  return (
    <Layout>
      <div className="flex flex-col lg:flex-row gap-8 items-start relative">

        {/* LEFT COLUMN: CONTROL PANEL */}
        <aside className="w-full lg:w-[400px] flex-shrink-0 space-y-6 lg:sticky lg:top-[120px]">
          <div className="bg-white pop-art-border pop-art-shadow p-6 relative">
            <div className="absolute -top-4 -left-4 bg-red-600 text-white font-comic px-4 py-1 pop-art-border-sm rotate-[-3deg] z-10 shadow-lg">
              STATION 01
            </div>

            <h2 className="text-3xl font-comic mb-6 uppercase border-b-4 border-black pb-2 flex items-center justify-between">
              CONFIGURATOR
              <i className="fas fa-cogs text-blue-600"></i>
            </h2>

            <div className="space-y-6">
              {/* STYLE SELECT */}
              <div className="space-y-3">
                <label className="block text-xs font-black uppercase tracking-tighter text-gray-400">Step 1: Choose Style</label>
                <div className="space-y-2">
                  {MOODS.map(m => (
                    <button
                      key={m.label}
                      onClick={() => setConfig({ ...config, mood: m.label })}
                      className={`w-full flex items-center gap-4 p-3 border-4 font-bold transition-all text-left ${
                        config.mood === m.label 
                          ? `${m.color} border-black translate-x-1 -translate-y-1 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]` 
                          : 'bg-white border-gray-200 hover:border-black text-gray-600'
                      }`}
                    >
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white pop-art-border-sm ${config.mood === m.label ? 'bg-black' : 'bg-gray-300'}`}>
                        <i className={`fas ${m.icon}`}></i>
                      </div>
                      <div>
                        <div className="text-sm uppercase leading-none mb-1">{m.label}</div>
                        <div className="text-[10px] leading-tight opacity-70">{m.desc}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* FILE UPLOAD */}
              <div className="space-y-3">
                <label className="block text-xs font-black uppercase tracking-tighter text-gray-400">Step 2: Upload Subject</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`group relative pop-art-border-sm border-dashed p-8 cursor-pointer transition-all flex flex-col items-center justify-center ${file ? 'bg-green-50 border-green-500' : 'bg-gray-50 border-gray-300 hover:bg-yellow-50 hover:border-black'}`}
                >
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                  <i className={`fas ${file ? 'fa-check-circle text-green-500' : 'fa-camera-retro text-black'} text-4xl mb-3 group-hover:scale-110 transition-transform`}></i>
                  <span className="text-sm font-black uppercase">{file ? 'PHOTO LOADED' : 'SNAP OR UPLOAD'}</span>
                  {file && <span className="text-[10px] font-bold text-gray-500 mt-2 truncate w-full text-center">{file.name}</span>}
                </div>
              </div>

              {/* INPUT FIELDS */}
              <div className="space-y-3">
                <label className="block text-xs font-black uppercase tracking-tighter text-gray-400">Step 3: Personalize</label>
                <div className="space-y-2">
                   <div className="relative">
                     <i className="fas fa-user-tag absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                     <input 
                       type="text" 
                       placeholder="NAMES (E.G. AYUSH & RUTVI)" 
                       value={config.coupleName}
                       onChange={(e) => setConfig({...config, coupleName: e.target.value})}
                       className="w-full pop-art-border-sm pl-10 p-2 text-xs font-bold uppercase focus:outline-none focus:border-red-500 bg-white"
                     />
                   </div>
                   <div className="relative">
                     <i className="fas fa-comment-dots absolute left-3 top-3 text-gray-400"></i>
                     <textarea 
                       placeholder="CAPTION OR MESSAGE..." 
                       value={config.customText}
                       onChange={(e) => setConfig({...config, customText: e.target.value})}
                       rows={2}
                       className="w-full pop-art-border-sm pl-10 p-2 text-xs font-bold uppercase focus:outline-none focus:border-blue-500 bg-white resize-none"
                     />
                   </div>
                </div>
              </div>

              {/* ACTION BUTTON */}
              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-4xl py-5 uppercase transition-all flex items-center justify-center gap-4 pop-art-border pop-art-shadow group active:translate-x-2 active:translate-y-2 active:shadow-none ${
                  !file || loading 
                    ? 'bg-gray-200 text-gray-400 border-gray-300 shadow-none' 
                    : 'bg-red-600 hover:bg-red-700 text-white'
                }`}
              >
                {loading ? (
                  <><i className="fas fa-atom fa-spin"></i> WORKING...</>
                ) : (
                  <><i className="fas fa-bolt group-hover:animate-bounce"></i> CREATE!</>
                )}
              </button>
            </div>
          </div>

          {/* HISTORY GALLERY */}
          {history.length > 0 && (
            <div className="bg-black p-4 pop-art-border pop-art-shadow-sm transform rotate-1">
              <h4 className="font-comic text-xl text-yellow-400 uppercase mb-3 border-b border-yellow-400/30">Your Recent Hits</h4>
              <div className="grid grid-cols-5 gap-2">
                {history.map((item, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => setResult(item)}
                    className={`border-2 border-white hover:scale-110 transition-all overflow-hidden aspect-square ${result?.timestamp === item.timestamp ? 'border-yellow-400 ring-2 ring-yellow-400' : 'opacity-60'}`}
                  >
                    <img src={item.imageUrl} className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </aside>

        {/* RIGHT COLUMN: WORKSPACE/CANVAS */}
        <section className="flex-grow w-full space-y-8">

          {/* ERROR ALERT */}
          {error && (
            <div className="bg-red-100 border-l-[12px] border-red-600 p-6 pop-art-border-sm animate-pop">
              <div className="flex items-center gap-4 text-red-800">
                <i className="fas fa-skull-crossbones text-4xl"></i>
                <div>
                  <h4 className="font-comic text-2xl uppercase italic">Critical Failure!</h4>
                  <p className="text-sm font-bold opacity-80">{error}</p>
                </div>
              </div>
            </div>
          )}

          {/* LOADING OVERLAY STATE */}
          {loading && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center relative overflow-hidden">
               <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(0,0,0,0.05)_1px,transparent_1px)] bg-[size:30px_30px]"></div>
               <div className="relative z-10 text-center space-y-12">
                 <div className="relative inline-block">
                    <div className="w-48 h-48 border-[12px] border-black border-t-blue-600 rounded-full animate-spin"></div>
                    <div className="absolute inset-6 border-[8px] border-black border-b-red-600 rounded-full animate-[spin_2s_linear_infinite_reverse]"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                      <i className="fas fa-mask text-5xl text-black animate-pulse"></i>
                    </div>
                 </div>
                 <div>
                   <h3 className="text-6xl font-comic uppercase tracking-tighter text-black mb-4 animate-bounce">
                     {loadingMsg}
                   </h3>
                   <p className="font-comic text-3xl text-red-600 uppercase italic opacity-70">The Art Engine is roaring!</p>
                 </div>
               </div>
            </div>
          )}

          {/* EMPTY / PREVIEW STATE */}
          {!loading && !result && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center border-dashed border-gray-300">
              {!previewUrl ? (
                <div className="max-w-md text-center space-y-8 animate-pop">
                  <div className="bg-yellow-400 pop-art-border p-12 rounded-full inline-block shadow-2xl rotate-3">
                    <i className="fas fa-image text-8xl text-black"></i>
                  </div>
                  <h3 className="text-6xl font-comic uppercase tracking-tighter leading-none">NO IMAGE DETECTED!</h3>
                  <p className="font-comic text-2xl text-gray-500 uppercase italic">Your canvas is waiting for a spark. Upload a photo in the configurator to start the transformation!</p>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center gap-8 animate-pop">
                  <div className="flex items-center justify-between w-full">
                    <h3 className="text-4xl font-comic uppercase text-blue-700 italic">Pre-Transformation Scan...</h3>
                    <div className="flex gap-4">
                       <button onClick={() => setPreviewUrl(null) || setFile(null)} className="font-comic text-xl text-red-500 hover:scale-105 transition-transform">REMOVE PHOTO</button>
                    </div>
                  </div>
                  <div className="relative group pop-art-border pop-art-shadow-sm overflow-hidden bg-gray-100 max-h-[600px]">
                    <img src={previewUrl} className="max-w-full h-auto block grayscale hover:grayscale-0 transition-all duration-700" />
                    <div className="absolute top-6 left-6 bg-black text-white px-6 py-2 font-comic text-4xl -rotate-6 pop-art-border-sm">SUBJECT A</div>
                    <div className="absolute bottom-6 right-6 bg-yellow-400 text-black px-6 py-2 font-comic text-3xl rotate-2 pop-art-border-sm shadow-xl">WAITING FOR ZAP...</div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* FINAL RESULT STATE */}
          {result && !loading && (
            <div className="space-y-8 animate-pop">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                <div>
                   <h3 className="text-6xl font-comic uppercase tracking-tighter leading-none text-black italic">
                     <span className="bg-red-600 text-white px-4 mr-3 pop-art-border-sm shadow-lg">BOOM!</span>
                     {config.mood}
                   </h3>
                   <p className="font-comic text-2xl text-blue-700 uppercase mt-2">Masterpiece Delivered</p>
                </div>
                <div className="flex gap-4 w-full md:w-auto">
                   <button 
                     onClick={() => handleDownload(result.imageUrl)}
                     className="flex-1 md:flex-none bg-green-500 hover:bg-green-600 text-white pop-art-border pop-art-shadow-sm px-10 py-4 font-comic text-3xl uppercase tracking-widest active:translate-x-1 active:translate-y-1 active:shadow-none transition-all"
                   >
                     <i className="fas fa-save mr-3"></i> DOWNLOAD
                   </button>
                </div>
              </div>

              {/* MAIN IMAGE WORKSPACE */}
              <div className="bg-white pop-art-border pop-art-shadow relative p-4 group">
                 <div className="relative overflow-hidden cursor-zoom-in bg-gray-50 min-h-[500px] flex items-center justify-center">
                    <img 
                      src={result.imageUrl} 
                      className="max-w-full h-auto block transform group-hover:scale-[1.01] transition-transform duration-1000" 
                    />

                    {/* Floating Comic Badges */}
                    <div className="absolute top-10 left-10 bg-yellow-400 pop-art-border-sm p-4 rotate-[-10deg] shadow-xl font-comic text-5xl text-black">
                      POW!
                    </div>
                    <div className="absolute bottom-10 right-10 bg-white pop-art-border-sm p-4 rotate-[5deg] shadow-xl font-comic text-3xl text-blue-600 italic">
                      THE GEMINI CUT
                    </div>
                 </div>
              </div>

              {/* COMPARISON AND SHARING */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 <div className="bg-white pop-art-border-sm p-4 rotate-1 opacity-80 hover:opacity-100 transition-all hover:-rotate-1">
                    <p className="font-comic text-sm uppercase text-gray-500 mb-2">Original Snapshot</p>
                    <img src={result.originalUrl} className="w-full h-48 object-cover pop-art-border-sm" />
                 </div>
                 <div className="lg:col-span-2 bg-black text-white p-6 pop-art-border-sm flex flex-col justify-center gap-4 relative overflow-hidden group">
