                    <h3 className="text-4xl font-comic uppercase text-blue-700 italic">Subject Ready for Zap!</h3>
                    <div className="flex gap-4">
                       <button onClick={() => setPreviewUrl(null) || setFile(null)} className="font-comic text-xl text-red-500 hover:scale-105 transition-transform border-b-2 border-red-500">CLEAR</button>
                    </div>
