                  <div className="relative group pop-art-border pop-art-shadow-sm overflow-hidden bg-gray-100 max-h-[600px]">
                    <img src={previewUrl} className="max-w-full h-auto block grayscale hover:grayscale-0 transition-all duration-700" />
                    <div className="absolute top-6 left-6 bg-black text-white px-6 py-2 font-comic text-4xl -rotate-6 pop-art-border-sm">ORIGINAL</div>
                    <div className="absolute bottom-6 right-6 bg-yellow-400 text-black px-6 py-2 font-comic text-3xl rotate-2 pop-art-border-sm shadow-xl">STANDBY...</div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* FINAL RESULT STATE */}
          {result && !loading && (
            <div className="space-y-8 animate-pop">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                <div>
                   <h3 className="text-6xl font-comic uppercase tracking-tighter leading-none text-black italic">
                     <span className="bg-red-600 text-white px-4 mr-3 pop-art-border-sm shadow-lg">BOOM!</span>
