                     <i className="fas fa-save mr-3"></i> DOWNLOAD
                   </button>
                </div>
              </div>

              {/* MAIN IMAGE WORKSPACE */}
              <div className="bg-white pop-art-border pop-art-shadow relative p-4 group">
                 <div className="relative overflow-hidden cursor-zoom-in bg-gray-50 min-h-[500px] flex items-center justify-center">
                    <img 
                      src={result.imageUrl} 
                      className="max-w-full h-auto block transform group-hover:scale-[1.01] transition-transform duration-1000" 
