              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 <div className="bg-white pop-art-border-sm p-4 rotate-1 opacity-80 hover:opacity-100 transition-all hover:-rotate-1">
                    <p className="font-comic text-sm uppercase text-gray-500 mb-2">Reference Source</p>
                    <img src={result.originalUrl} className="w-full h-48 object-cover pop-art-border-sm" />
                 </div>
                 <div className="lg:col-span-2 bg-black text-white p-6 pop-art-border-sm flex flex-col justify-center gap-4 relative overflow-hidden">
                    <div className="relative z-10">
                      <h4 className="font-comic text-4xl text-yellow-400 mb-2 uppercase">GO VIRAL!</h4>
