                      </div>
                    </div>
                 </div>
              </div>
            </div>
          )}
        </section>
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: { label: PopArtMood; icon: string; color: string; desc: string }[] = [
  { label: 'Classic Pop Art', icon: 'fa-palette', color: 'bg-yellow-400', desc: 'Lichtenstein-inspired dots and primary colors.' },
  { label: 'Futuristic Pop', icon: 'fa-user-astronaut', color: 'bg-purple-600', desc: 'Neon glows, holographic grids, and cyberpunk flair.' },
  { label: 'Retro Comic', icon: 'fa-book-open', color: 'bg-blue-500', desc: '1960s silver age comic book style.' },
  { label: 'Funny/Caricature', icon: 'fa-laugh-squint', color: 'bg-green-500', desc: 'Exaggerated features and wacky colors.' },
  { label: 'Emotional/Dramatic', icon: 'fa-bolt', color: 'bg-red-500', desc: 'High contrast noir-meets-color drama.' }
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [history, setHistory] = useState<TransformationResult[]>([]);
  const [loadingMsg, setLoadingMsg] = useState("");

  const loadingMessages = [
    "Analyzing visual structure...",
    "Injecting halftone energy...",
    "Sharpening ink contours...",
    "Applying vector registration...",
    "Finalizing comic aesthetic..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (loading) {
      let i = 0;
      const interval = setInterval(() => {
        setLoadingMsg(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);
    setLoadingMsg(loadingMessages[0]);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      const newResult = {
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      };
      setResult(newResult);
      setHistory(prev => [newResult, ...prev].slice(0, 5));
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = (url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `pop-magic-${Date.now()}.png`;
    link.click();
  };

  return (
    <Layout>
      <div className="flex flex-col lg:flex-row gap-8 items-start relative">

        {/* LEFT COLUMN: CONTROL PANEL */}
        <aside className="w-full lg:w-[420px] flex-shrink-0 space-y-6 lg:sticky lg:top-[120px]">
          <div className="bg-white pop-art-border pop-art-shadow p-6 relative">
            <div className="absolute -top-4 -left-4 bg-red-600 text-white font-comic px-4 py-1 pop-art-border-sm rotate-[-3deg] z-10 shadow-lg text-lg">
              STATION 01
            </div>

            <h2 className="text-3xl font-comic mb-6 uppercase border-b-4 border-black pb-2 flex items-center justify-between mt-2">
              CONFIGURATOR
              <i className="fas fa-cogs text-blue-600"></i>
            </h2>

            <div className="space-y-6">
              {/* STYLE SELECT */}
              <div className="space-y-3">
                <label className="block text-sm font-black uppercase tracking-tighter text-black">Step 1: Choose Art Style</label>
                <div className="space-y-2">
                  {MOODS.map(m => (
                    <button
                      key={m.label}
                      onClick={() => setConfig({ ...config, mood: m.label })}
                      className={`w-full flex items-center gap-4 p-3 border-4 font-bold transition-all text-left ${
                        config.mood === m.label 
                          ? `${m.color} border-black translate-x-1 -translate-y-1 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]` 
                          : 'bg-white border-gray-200 hover:border-black text-gray-600'
                      }`}
                    >
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white pop-art-border-sm ${config.mood === m.label ? 'bg-black' : 'bg-gray-300'}`}>
                        <i className={`fas ${m.icon}`}></i>
                      </div>
                      <div>
                        <div className="text-sm uppercase leading-none mb-1">{m.label}</div>
                        <div className="text-[10px] leading-tight opacity-70">{m.desc}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* FILE UPLOAD */}
              <div className="space-y-3">
                <label className="block text-sm font-black uppercase tracking-tighter text-black">Step 2: Upload Your Photo</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`group relative pop-art-border-sm border-dashed p-8 cursor-pointer transition-all flex flex-col items-center justify-center ${file ? 'bg-green-50 border-green-500' : 'bg-gray-50 border-gray-300 hover:bg-yellow-50 hover:border-black'}`}
                >
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                  <i className={`fas ${file ? 'fa-check-circle text-green-500' : 'fa-camera-retro text-black'} text-5xl mb-3 group-hover:scale-110 transition-transform`}></i>
                  <span className="text-sm font-black uppercase">{file ? 'PHOTO READY!' : 'TAP TO UPLOAD'}</span>
                  {file && <span className="text-xs font-bold text-black mt-2 truncate w-full text-center bg-white/80 px-2 py-1 border border-black">{file.name}</span>}
                </div>
              </div>

              {/* INPUT FIELDS - HIGH CONTRAST */}
              <div className="space-y-4">
                <label className="block text-sm font-black uppercase tracking-tighter text-black">Step 3: Personalize Your Art</label>
                <div className="space-y-4">
                   <div className="group">
                     <div className="flex items-center gap-2 mb-1">
                        <i className="fas fa-user-tag text-red-600"></i>
                        <span className="text-[10px] font-black uppercase text-gray-400">Add Names:</span>
                     </div>
                     <input 
                       type="text" 
                       placeholder="e.g. Ayush & Rutvi" 
                       value={config.coupleName}
                       onChange={(e) => setConfig({...config, coupleName: e.target.value})}
                       className="w-full pop-art-border-sm px-4 py-4 text-xl font-bold text-black focus:outline-none focus:ring-4 focus:ring-red-500/30 focus:border-red-600 bg-yellow-50 placeholder:text-gray-400 placeholder:font-normal transition-all"
                     />
                   </div>
                   <div className="group">
                     <div className="flex items-center gap-2 mb-1">
                        <i className="fas fa-comment-dots text-blue-600"></i>
                        <span className="text-[10px] font-black uppercase text-gray-400">Add Caption:</span>
                     </div>
                     <textarea 
                       placeholder="Type your comic message..." 
                       value={config.customText}
                       onChange={(e) => setConfig({...config, customText: e.target.value})}
                       rows={3}
                       className="w-full pop-art-border-sm px-4 py-4 text-xl font-bold text-black focus:outline-none focus:ring-4 focus:ring-blue-500/30 focus:border-blue-600 bg-yellow-50 resize-none placeholder:text-gray-400 placeholder:font-normal transition-all"
                     />
                   </div>
                </div>
              </div>

              {/* ACTION BUTTON */}
              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-4xl py-6 uppercase transition-all flex items-center justify-center gap-4 pop-art-border pop-art-shadow group active:translate-x-2 active:translate-y-2 active:shadow-none ${
                  !file || loading 
                    ? 'bg-gray-200 text-gray-400 border-gray-300 shadow-none' 
                    : 'bg-red-600 hover:bg-red-700 text-white'
                }`}
              >
                {loading ? (
                  <><i className="fas fa-atom fa-spin"></i> ZAPPING...</>
                ) : (
                  <><i className="fas fa-bolt group-hover:animate-bounce"></i> CREATE ART!</>
                )}
              </button>
            </div>
          </div>

          {/* HISTORY GALLERY */}
          {history.length > 0 && (
            <div className="bg-black p-4 pop-art-border pop-art-shadow-sm transform rotate-1">
              <h4 className="font-comic text-xl text-yellow-400 uppercase mb-3 border-b border-yellow-400/30">Recent Hits</h4>
              <div className="grid grid-cols-5 gap-2">
                {history.map((item, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => setResult(item)}
                    className={`border-2 border-white hover:scale-110 transition-all overflow-hidden aspect-square ${result?.timestamp === item.timestamp ? 'border-yellow-400 ring-2 ring-yellow-400' : 'opacity-60'}`}
                  >
                    <img src={item.imageUrl} className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </aside>

        {/* RIGHT COLUMN: WORKSPACE/CANVAS */}
        <section className="flex-grow w-full space-y-8">

          {/* ERROR ALERT */}
          {error && (
            <div className="bg-red-100 border-l-[12px] border-red-600 p-6 pop-art-border-sm animate-pop">
              <div className="flex items-center gap-4 text-red-800">
                <i className="fas fa-skull-crossbones text-4xl"></i>
                <div>
                  <h4 className="font-comic text-2xl uppercase italic">ZAP FAILED!</h4>
                  <p className="text-sm font-bold opacity-80">{error}</p>
                </div>
              </div>
            </div>
          )}

          {/* LOADING STATE */}
          {loading && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center relative overflow-hidden">
               <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(0,0,0,0.05)_1px,transparent_1px)] bg-[size:30px_30px]"></div>
               <div className="relative z-10 text-center space-y-12">
                 <div className="relative inline-block">
                    <div className="w-48 h-48 border-[12px] border-black border-t-blue-600 rounded-full animate-spin"></div>
                    <div className="absolute inset-6 border-[8px] border-black border-b-red-600 rounded-full animate-[spin_2s_linear_infinite_reverse]"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                      <i className="fas fa-mask text-5xl text-black animate-pulse"></i>
                    </div>
                 </div>
                 <div>
                   <h3 className="text-6xl font-comic uppercase tracking-tighter text-black mb-4 animate-bounce">
                     {loadingMsg}
                   </h3>
                   <p className="font-comic text-3xl text-red-600 uppercase italic opacity-70">Powering up the ink jet!</p>
                 </div>
               </div>
            </div>
          )}

          {/* EMPTY / PREVIEW STATE */}
          {!loading && !result && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center border-dashed border-gray-300">
              {!previewUrl ? (
                <div className="max-w-md text-center space-y-8 animate-pop">
                  <div className="bg-yellow-400 pop-art-border p-12 rounded-full inline-block shadow-2xl rotate-3">
                    <i className="fas fa-image text-8xl text-black"></i>
                  </div>
                  <h3 className="text-6xl font-comic uppercase tracking-tighter leading-none">NO PHOTO YET!</h3>
                  <p className="font-comic text-2xl text-gray-500 uppercase italic">Your comic journey starts with a photo. Upload one on the left to begin!</p>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center gap-8 animate-pop">
                  <div className="flex items-center justify-between w-full">
