import { GoogleGenAI } from "@google/genai";
import { PopArtConfig } from "../types";

export const transformToPopArt = async (
  base64Image: string,
  mimeType: string,
  config: PopArtConfig
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let styleSpecifics = '';
  switch (config.mood) {
    case 'Futuristic Pop':
      styleSpecifics = `
        - Use a Neon-Cyberpunk color palette (Neon Pink, Electric Blue, Acid Green).
        - Add holographic textures and glowing circuit-board patterns in the background.
        - Subjects should have glowing neon outlines.
      `;
      break;
    case 'Synthwave Glow':
      styleSpecifics = `
        - 80s aesthetics: intense purples, magentas, and deep blues.
        - Background should feature a retro-future sun and a perspective grid floor.
        - Add a soft "glow" or bloom effect to the edges of the subjects.
      `;
      break;
    case 'Graffiti Urban':
      styleSpecifics = `
        - Street art style with visible spray paint drips and gritty textures.
        - Background: brick wall with layered tags and vibrant urban graffiti patterns.
        - Thick, slightly messy black outlines to mimic a broad-tip marker.
      `;
      break;
    case 'Vintage 50s Ad':
      styleSpecifics = `
        - Use a muted pastel color palette (teal, cream, soft pink, mustard).
        - Clean, elegant ink lines inspired by 1950s commercial illustration.
        - Simple geometric or solid-color backgrounds with a paper texture overlay.
      `;
      break;
    case 'Manga Noir':
      styleSpecifics = `
        - Dramatic high-contrast black and white (no colors).
        - Use traditional manga screen-tones (dot patterns) for shading.
        - Dynamic speed lines and bold focus lines in the background.
      `;
      break;
    default:
      styleSpecifics = `- Use clean vector-style edges and flat pop-art color fills (Cyan, Magenta, Yellow, Black palettes).`;
  }

  const prompt = `
    Transform this uploaded image into a professional ${config.mood} style illustration.

    CRITICAL IDENTITY PROTECTION:
    - **DO NOT CHANGE THE PERSON'S FACE.** 
    - Maintain the exact likeness, facial features, and expressions of the subjects in the original photo.
    - The identity of the person must be 100% recognizable. Apply the artistic style OVER their features, not by replacing them.

    CRITICAL VISUAL STYLE RULES:
    - Apply bold, thick black comic ink outlines to all subjects (unless Manga Noir).
    ${styleSpecifics}
    - Incorporate high-quality halftone dot shading (Ben-Day dots) for depth.
    - BACKGROUND: Replace the current background with a dynamic, high-energy comic burst, speed lines, or style-specific patterns mentioned above.
    - Ensure the colors are vibrant and saturated (except for Noir styles).

    TEXT OVERLAY INSTRUCTIONS:
    ${config.coupleName ? `- Stylistically render the names "${config.coupleName}" in a rectangular "caption box" or a vibrant corner banner.` : ''}
    ${config.customText ? `- Add a comic speech bubble or an action-oriented "caption box" containing the text: "${config.customText}".` : ''}

    Make it look like a premium comic cover or a high-end gallery pop-art piece.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1] || base64Image,
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    let generatedImageUrl = '';
    if (response.candidates && response.candidates[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          generatedImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!generatedImageUrl) {
      throw new Error("No image data returned from the model. Try a different mood or image.");
    }

    return generatedImageUrl;
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Failed to generate art. Please check your API key and connection.");
  }
};

