                 </div>
                 <div>
                   <h3 className="text-6xl font-comic uppercase tracking-tighter text-black mb-4 animate-bounce">
                     {loadingMsg}
                   </h3>
                   <p className="font-comic text-3xl text-red-600 uppercase italic opacity-70">Art of Timeline is thinking...</p>
                 </div>
               </div>
            </div>
          )}

          {/* EMPTY / PREVIEW STATE */}
          {!loading && !result && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center border-dashed border-gray-300">
              {!previewUrl ? (
