                      className="max-w-full h-auto block transform group-hover:scale-[1.01] transition-transform duration-1000" 
                    />
                    <div className="absolute bottom-6 right-6 flex flex-col items-end gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                       <span className="bg-black text-white px-3 py-1 font-comic text-xl uppercase rotate-[-2deg]">Art of Timeline</span>
                       <span className="text-[10px] font-black text-black uppercase tracking-tighter bg-white/80 px-2 border border-black">Authentic Generation</span>
                    </div>
                 </div>
              </div>

              {/* REFINED BOTTOM AREA */}
              <div className="bg-blue-700 text-white pop-art-border p-8 pop-art-shadow-sm flex items-start gap-6">
                 <div className="bg-white text-blue-700 p-4 pop-art-border-sm rounded-full rotate-12 flex-shrink-0">
                    <i className="fas fa-lightbulb text-4xl"></i>
                 </div>
