import React, { useState, useRef, useEffect } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: { label: PopArtMood; icon: string; color: string; desc: string }[] = [
  { label: 'Classic Pop Art', icon: 'fa-palette', color: 'bg-yellow-400', desc: 'Lichtenstein-inspired dots and primary colors.' },
  { label: 'Futuristic Pop', icon: 'fa-user-astronaut', color: 'bg-purple-600', desc: 'Neon glows, holographic grids, and cyberpunk flair.' },
  { label: 'Retro Comic', icon: 'fa-book-open', color: 'bg-blue-500', desc: '1960s silver age comic book style.' },
  { label: 'Funny/Caricature', icon: 'fa-laugh-squint', color: 'bg-green-500', desc: 'Exaggerated features and wacky colors.' },
  { label: 'Emotional/Dramatic', icon: 'fa-bolt', color: 'bg-red-500', desc: 'High contrast noir-meets-color drama.' },
  { label: 'Synthwave Glow', icon: 'fa-sun', color: 'bg-pink-500', desc: '80s retro-future with purple haze and neon grids.' },
  { label: 'Graffiti Urban', icon: 'fa-spray-can', color: 'bg-orange-500', desc: 'Street art style with spray drips and gritty textures.' },
  { label: 'Vintage 50s Ad', icon: 'fa-tv', color: 'bg-teal-400', desc: 'Mid-century pastel tones and clean commercial ink.' },
  { label: 'Manga Noir', icon: 'fa-shuriken', color: 'bg-gray-800', desc: 'Sharp black & white Japanese manga with screen tones.' }
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [history, setHistory] = useState<TransformationResult[]>([]);
  const [loadingMsg, setLoadingMsg] = useState("");

  const loadingMessages = [
    "Analyzing visual structure...",
    "Injecting halftone energy...",
    "Sharpening ink contours...",
    "Applying vector registration...",
    "Finalizing comic aesthetic..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (loading) {
      let i = 0;
      const interval = setInterval(() => {
        setLoadingMsg(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);
    setLoadingMsg(loadingMessages[0]);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      const newResult = {
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      };
      setResult(newResult);
      setHistory(prev => [newResult, ...prev].slice(0, 5));
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = (url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `bhishm-patel-art-${Date.now()}.png`;
    link.click();
  };

  return (
    <Layout>
      <div className="flex flex-col lg:flex-row gap-8 items-start relative">

        {/* LEFT COLUMN: CONTROL PANEL */}
        <aside className="w-full lg:w-[420px] flex-shrink-0 space-y-6 lg:sticky lg:top-[120px]">
          <div className="bg-white pop-art-border pop-art-shadow p-6 relative">
            <div className="absolute -top-3 -left-3 bg-red-600 text-white font-comic px-3 py-1 pop-art-border-sm rotate-[-2deg] z-10 shadow-lg text-sm uppercase">
              Bhishm Patel
            </div>

            <h2 className="text-3xl font-comic mb-6 uppercase border-b-4 border-black pb-2 flex items-center justify-between mt-2 text-black">
              CONFIGURATOR
              <i className="fas fa-bolt text-red-600 animate-pulse text-sm"></i>
            </h2>

            <div className="space-y-6">
              {/* STYLE SELECT */}
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-black opacity-50">Step 1: Choose Art Style</label>
                <div className="grid grid-cols-1 gap-2">
                  {MOODS.map(m => (
                    <button
                      key={m.label}
                      onClick={() => setConfig({ ...config, mood: m.label })}
                      className={`w-full flex items-center gap-4 p-3 border-4 font-bold transition-all text-left ${
                        config.mood === m.label 
                          ? `${m.color} border-black translate-x-1 -translate-y-1 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] text-black` 
                          : 'bg-white border-gray-200 hover:border-black text-gray-600'
                      }`}
                    >
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white pop-art-border-sm ${config.mood === m.label ? 'bg-black' : 'bg-gray-300'}`}>
                        <i className={`fas ${m.icon}`}></i>
                      </div>
                      <div>
                        <div className="text-sm uppercase leading-none mb-1">{m.label}</div>
                        <div className="text-[10px] leading-tight opacity-70">{m.desc}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* FILE UPLOAD */}
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-black opacity-50">Step 2: Upload Your Photo</label>
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`group relative pop-art-border-sm border-dashed p-8 cursor-pointer transition-all flex flex-col items-center justify-center ${file ? 'bg-green-50 border-green-500' : 'bg-gray-50 border-gray-300 hover:bg-yellow-50 hover:border-black'}`}
                >
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                  <i className={`fas ${file ? 'fa-check-circle text-green-500' : 'fa-camera-retro text-black'} text-4xl mb-3 group-hover:scale-110 transition-transform`}></i>
                  <span className="text-xs font-black uppercase text-black">{file ? 'PHOTO READY!' : 'TAP TO UPLOAD'}</span>
                  {file && <span className="text-[10px] font-bold text-black mt-2 truncate w-full text-center bg-white/80 px-2 py-1 border border-black">{file.name}</span>}
                </div>
              </div>

              {/* INPUT FIELDS - HIGH CONTRAST */}
              <div className="space-y-4">
                <label className="block text-[10px] font-black uppercase tracking-widest text-black opacity-50">Step 3: Personalize Your Art</label>
                <div className="space-y-4">
                   <div className="group">
                     <div className="flex items-center gap-2 mb-1">
                        <i className="fas fa-user-tag text-red-600 text-xs"></i>
                        <span className="text-[10px] font-black uppercase text-gray-400 tracking-tighter">Add Names:</span>
                     </div>
                     <input 
                       type="text" 
                       placeholder="e.g. Ayush & Rutvi" 
                       value={config.coupleName}
                       onChange={(e) => setConfig({...config, coupleName: e.target.value})}
                       className="w-full pop-art-border-sm px-4 py-3 text-lg font-bold text-black focus:outline-none focus:ring-4 focus:ring-red-500/30 focus:border-red-600 bg-yellow-50 placeholder:text-gray-300 placeholder:font-normal transition-all"
                     />
                   </div>
                   <div className="group">
                     <div className="flex items-center gap-2 mb-1">
                        <i className="fas fa-comment-dots text-blue-600 text-xs"></i>
                        <span className="text-[10px] font-black uppercase text-gray-400 tracking-tighter">Add Caption:</span>
                     </div>
                     <textarea 
                       placeholder="Type your message..." 
                       value={config.customText}
                       onChange={(e) => setConfig({...config, customText: e.target.value})}
                       rows={2}
                       className="w-full pop-art-border-sm px-4 py-3 text-lg font-bold text-black focus:outline-none focus:ring-4 focus:ring-blue-500/30 focus:border-blue-600 bg-yellow-50 resize-none placeholder:text-gray-300 placeholder:font-normal transition-all"
                     />
                   </div>
                </div>
              </div>

              {/* ACTION BUTTON */}
              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-4xl py-6 uppercase transition-all flex items-center justify-center gap-4 pop-art-border pop-art-shadow group active:translate-x-2 active:translate-y-2 active:shadow-none ${
                  !file || loading 
                    ? 'bg-gray-200 text-gray-400 border-gray-300 shadow-none' 
                    : 'bg-red-600 hover:bg-red-700 text-white'
                }`}
              >
                {loading ? (
                  <><i className="fas fa-atom fa-spin"></i> ZAPPING...</>
                ) : (
                  <><i className="fas fa-bolt group-hover:animate-bounce"></i> CREATE!</>
                )}
              </button>
            </div>
          </div>

          <div className="bg-white/50 p-2 text-center transform -rotate-1 border border-black/5">
             <p className="text-[8px] font-black uppercase text-black/20 tracking-[0.3em]">Created by Bhishm Patel</p>
          </div>
        </aside>

        {/* RIGHT COLUMN: WORKSPACE/CANVAS */}
        <section className="flex-grow w-full space-y-8">

          {/* ERROR ALERT */}
          {error && (
            <div className="bg-red-100 border-l-[12px] border-red-600 p-6 pop-art-border-sm animate-pop">
              <div className="flex items-center gap-4 text-red-800">
                <i className="fas fa-skull-crossbones text-4xl"></i>
                <div>
                  <h4 className="font-comic text-2xl uppercase italic leading-none mb-1">ZAP FAILED!</h4>
                  <p className="text-xs font-bold opacity-80">{error}</p>
                </div>
              </div>
            </div>
          )}

          {/* LOADING STATE */}
          {loading && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center relative overflow-hidden">
               <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(0,0,0,0.05)_1px,transparent_1px)] bg-[size:30px_30px]"></div>
               <div className="relative z-10 text-center space-y-12">
                 <div className="relative inline-block">
                    <div className="w-40 h-40 border-[10px] border-black border-t-blue-600 rounded-full animate-spin"></div>
                    <div className="absolute inset-5 border-[6px] border-black border-b-red-600 rounded-full animate-[spin_2s_linear_infinite_reverse]"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                      <i className="fas fa-mask text-4xl text-black animate-pulse"></i>
                    </div>
                 </div>
                 <div>
                   <h3 className="text-5xl font-comic uppercase tracking-tighter text-black mb-4 animate-bounce">
                     {loadingMsg}
                   </h3>
                   <p className="font-comic text-2xl text-red-600 uppercase italic opacity-70">Bhishm Patel's engine is processing...</p>
                 </div>
               </div>
            </div>
          )}

          {/* EMPTY / PREVIEW STATE */}
          {!loading && !result && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center border-dashed border-gray-300">
              {!previewUrl ? (
                <div className="max-w-md text-center space-y-8 animate-pop">
                  <div className="bg-yellow-400 pop-art-border p-12 rounded-full inline-block shadow-2xl rotate-3">
                    <i className="fas fa-image text-8xl text-black"></i>
                  </div>
                  <h3 className="text-6xl font-comic uppercase tracking-tighter leading-none text-black">NO PHOTO YET!</h3>
                  <p className="font-comic text-2xl text-gray-500 uppercase italic">Upload a photo to see the magic!</p>
                  <p className="text-[9px] font-black text-black opacity-20 uppercase tracking-[0.5em]">Created by Bhishm Patel</p>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center gap-8 animate-pop">
                  <div className="flex items-center justify-between w-full">
                    <h3 className="text-3xl font-comic uppercase text-blue-700 italic">Ready to transform</h3>
                    <div className="flex gap-4">
                       <button onClick={() => setPreviewUrl(null) || setFile(null)} className="font-comic text-lg text-red-500 hover:scale-105 transition-transform border-b border-red-500 leading-none">RESET</button>
                    </div>
                  </div>
                  <div className="relative group pop-art-border pop-art-shadow-sm overflow-hidden bg-gray-100 max-h-[700px] w-full flex items-center justify-center">
                    <img src={previewUrl} className="max-w-full h-auto block grayscale hover:grayscale-0 transition-all duration-700" />
                    <div className="absolute top-4 right-4 text-[8px] font-black uppercase tracking-widest opacity-20 text-black">B. Patel Engine</div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* FINAL RESULT STATE */}
          {result && !loading && (
            <div className="space-y-8 animate-pop">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                <div>
                   <h3 className="text-5xl font-comic uppercase tracking-tighter leading-none text-black italic">
                     <span className="bg-red-600 text-white px-3 mr-3 pop-art-border-sm shadow-lg">ZAP!</span>
