    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [history, setHistory] = useState<TransformationResult[]>([]);
  const [loadingMsg, setLoadingMsg] = useState("");

  const loadingMessages = [
    "Charging neon circuits...",
    "Splashing electric ink...",
    "Synthesizing hyper-colors...",
    "Calibrating saturation levels...",
    "Finalizing masterpiece..."
  ];

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (loading) {
      let i = 0;
      const interval = setInterval(() => {
        setLoadingMsg(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(selectedFile);
    }
  };

  const handleCreateArt = async () => {
    if (!previewUrl || !file) return;

    setLoading(true);
    setError(null);
    setLoadingMsg(loadingMessages[0]);

    try {
      const generatedUrl = await transformToPopArt(previewUrl, file.type, config);
      const newResult = {
        imageUrl: generatedUrl,
        originalUrl: previewUrl,
        timestamp: Date.now()
      };
      setResult(newResult);
      setHistory(prev => [newResult, ...prev].slice(0, 5));
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

