                  <span className="text-sm font-black uppercase text-black">{file ? 'READY FOR ZAPPING!' : 'TAP TO UPLOAD'}</span>
                  {file && <span className="text-[10px] font-bold text-black mt-2 truncate w-full text-center bg-white px-2 py-1 border border-black">{file.name}</span>}
                </div>
              </div>

              {/* ACTION BUTTON */}
              <button
                disabled={!file || loading}
                onClick={handleCreateArt}
                className={`w-full font-comic text-4xl py-6 uppercase transition-all flex items-center justify-center gap-4 pop-art-border pop-art-shadow group active:translate-x-2 active:translate-y-2 active:shadow-none ${
