                   <p className="font-comic text-2xl text-[#ff00ff] uppercase italic drop-shadow-md">Injecting Pure Energy!</p>
                 </div>
               </div>
            </div>
          )}

          {/* EMPTY / PREVIEW STATE */}
          {!loading && !result && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[700px] flex flex-col items-center justify-center border-dashed border-black/20">
              {!previewUrl ? (
