import { GoogleGenAI } from "@google/genai";
import { PopArtConfig } from "../types";

export const transformToPopArt = async (
  base64Image: string,
  mimeType: string,
  config: PopArtConfig
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let styleSpecifics = '';
  switch (config.mood) {
    case 'Cartoonish Pop Art':
      styleSpecifics = `
        - Style: Playful 2D cartoon/animation aesthetic.
        - Exaggerate features slightly (e.g., expressive eyes, bouncy hair) but keep likeness recognizable.
        - Palette: Use high-energy, warm colors (Bright Yellow, Tangerine, Bubblegum Pink, Lime).
        - Outlines: Very thick, smooth, and rounded black ink outlines.
        - Shading: Clean cel-shading with clear highlight zones.
      `;
      break;
    case 'Futuristic Pop':
      styleSpecifics = `
        - Use a Hyper-Neon color palette (Fluorescent Pink, Electric Cyan, Acid Lime).
        - Add glowing holographic textures and vibrant circuit patterns.
        - Subjects must have thick glowing neon halos.
      `;
      break;
    case 'Synthwave Glow':
      styleSpecifics = `
        - Radical 80s aesthetics: intense hot pinks, ultraviolet purples, and electric blues.
        - Background: Retro-future sunset with vibrant orange and magenta gradients.
        - High-bloom glow on all light-reflecting surfaces.
      `;
      break;
    case 'Graffiti Urban':
      styleSpecifics = `
        - Gritty street art with explosive color splatters (Yellow, Orange, Blue).
        - Background: Multi-colored graffiti wall with "drip" effects.
        - High-contrast marker strokes with vibrant fill patterns.
      `;
      break;
    case 'Vintage 50s Ad':
      styleSpecifics = `
        - While keeping a vintage feel, boost the saturation of teals, corals, and yellows.
        - Clean, punchy commercial ink lines with high-energy pastel backgrounds.
      `;
      break;
    case 'Manga Noir':
      styleSpecifics = `
        - Keep strictly dramatic high-contrast black and white.
        - Use dense, sharp screen-tones for a premium graphic feel.
      `;
      break;
    case 'Anime Inspired':
      styleSpecifics = `
        - Ultra-vibrant "Shonen" color palette.
        - Dynamic lighting with bright "God rays" or energy particles.
        - Cel-shaded with high-contrast color zones and vivid highlights.
      `;
      break;
    default:
      styleSpecifics = `- Use extreme saturation, bold primary colors (Cyan, Magenta, Yellow), and flat pop-art fills with zero muddy tones.`;
  }

  const prompt = `
    Transform this uploaded image into a professional ${config.mood} style illustration with HYPER-VIBRANT COLORS.

    CRITICAL COLOR INSTRUCTIONS:
    - Use a highly saturated, vivid, and electric color palette. 
    - Colors should "pop" off the screen. 
    - Avoid any muted, dull, or realistic skin tones; instead, use artistic, vibrant interpretations.

    CRITICAL IDENTITY PROTECTION:
    - **DO NOT CHANGE THE PERSON'S FACE.** 
    - Maintain the exact likeness, facial features, and expressions of the subjects in the original photo.
    - The identity of the person must be 100% recognizable. Apply the artistic style OVER their features, not by replacing them.

    CRITICAL VISUAL STYLE RULES:
    - Apply bold, thick black comic ink outlines to all subjects (unless Manga Noir).
    ${styleSpecifics}
    - Incorporate high-quality, colorful halftone dot shading for texture.
    - BACKGROUND: Replace the current background with a dynamic, high-energy burst of colors, speed lines, or explosive geometric shapes.

    TEXT OVERLAY INSTRUCTIONS:
    ${config.coupleName ? `- Stylistically render the names "${config.coupleName}" in a vibrant, high-contrast rectangular "caption box".` : ''}
    ${config.customText ? `- Add a comic speech bubble or an action "caption box" containing the text: "${config.customText}".` : ''}

    The final image must look like a high-end, colorful pop-art gallery piece.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1] || base64Image,
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    let generatedImageUrl = '';
    if (response.candidates && response.candidates[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          generatedImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!generatedImageUrl) {
      throw new Error("No image data returned from the model. Try a different mood or image.");
    }

    return generatedImageUrl;
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Failed to generate art. Please check your API key and connection.");
  }
};

import React, { useState, useRef, useEffect } from 'react';
import Layout from './components/Layout';
import { PopArtConfig, PopArtMood, TransformationResult } from './types';
import { transformToPopArt } from './services/geminiService';

const MOODS: { label: PopArtMood; icon: string; color: string; desc: string }[] = [
  { label: 'Classic Pop Art', icon: 'fa-palette', color: 'bg-[#ff00ff]', desc: 'Lichtenstein-inspired dots and primary colors.' },
  { label: 'Cartoonish Pop Art', icon: 'fa-mask', color: 'bg-[#ffd700]', desc: 'Playful animation style with bold, bouncy colors.' },
  { label: 'Futuristic Pop', icon: 'fa-user-astronaut', color: 'bg-[#00ffff]', desc: 'Neon glows, holographic grids, and cyberpunk flair.' },
  { label: 'Retro Comic', icon: 'fa-book-open', color: 'bg-[#ffde03]', desc: '1960s silver age comic book style.' },
  { label: 'Funny/Caricature', icon: 'fa-laugh-squint', color: 'bg-[#39ff14]', desc: 'Exaggerated features and wacky colors.' },
  { label: 'Emotional/Dramatic', icon: 'fa-bolt', color: 'bg-[#ff3131]', desc: 'High contrast noir-meets-color drama.' },
  { label: 'Synthwave Glow', icon: 'fa-sun', color: 'bg-[#bc13fe]', desc: '80s retro-future with purple haze and neon grids.' },
  { label: 'Graffiti Urban', icon: 'fa-spray-can', color: 'bg-[#ffae42]', desc: 'Street art style with spray drips and gritty textures.' },
  { label: 'Vintage 50s Ad', icon: 'fa-tv', color: 'bg-[#1abc9c]', desc: 'Mid-century pastel tones and clean commercial ink.' },
  { label: 'Manga Noir', icon: 'fa-shuriken', color: 'bg-[#000000]', desc: 'Sharp black & white Japanese manga with screen tones.' },
  { label: 'Anime Inspired', icon: 'fa-fire', color: 'bg-[#4b0082]', desc: 'Modern anime look with vibrant cel-shading and dynamic energy.' }
];

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [config, setConfig] = useState<PopArtConfig>({
    mood: 'Classic Pop Art',
    coupleName: '',
    customText: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TransformationResult | null>(null);
  const [loadingMsg, setLoadingMsg] = useState("");

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadingMessages = [
    "Scanning environment...",
    "Detecting subjects...",
    "Auto-generating captions...",
    "Synthesizing hyper-colors...",
    "Finalizing masterpiece..."
  ];

  useEffect(() => {
    if (loading) {
      let i = 0;
      const interval = setInterval(() => {
        setLoadingMsg(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loading]);

  const startCamera = async () => {
    setIsCameraActive(true);
    setPreviewUrl(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setError("Camera access denied or not available.");
      setIsCameraActive(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/png');
        setPreviewUrl(dataUrl);

        // Stop camera
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
        setIsCameraActive(false);

        // Convert to file for processing
        fetch(dataUrl)
          .then(res => res.blob())
          .then(blob => {
            const capturedFile = new File([blob], "capture.png", { type: "image/png" });
            setFile(capturedFile);
          });
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setResult(null);
        setError(null);
