                {loading ? <><i className="fas fa-atom fa-spin"></i> GENERATING 3X...</> : <><i className="fas fa-magic"></i> TRANSFORM!</>}
              </button>
            </div>
          </div>
        </aside>

        {/* RIGHT COLUMN: WORKSPACE */}
