                 <p className="font-comic text-2xl text-[#ff00ff] uppercase italic">Triple the Power, Triple the Vibes!</p>
               </div>
            </div>
          )}

          {!loading && isCameraActive && (
            <div className="bg-black pop-art-border pop-art-shadow p-4 min-h-[600px] flex flex-col items-center justify-center relative">
               <video ref={videoRef} autoPlay playsInline className="max-w-full h-auto rounded-lg shadow-2xl" />
               <canvas ref={canvasRef} className="hidden" />
               <div className="mt-8 flex gap-4">
                 <button onClick={capturePhoto} className="bg-[#39ff14] text-black font-comic text-4xl px-12 py-4 pop-art-border pop-art-shadow-sm hover:scale-105 active:scale-95 transition-all">
                    CAPTURE!
                 </button>
                 <button onClick={() => setIsCameraActive(false)} className="bg-white text-black font-comic text-4xl px-8 py-4 pop-art-border pop-art-shadow-sm hover:scale-105 active:scale-95 transition-all">
                    CANCEL
                 </button>
               </div>
            </div>
          )}

          {!loading && !isCameraActive && results.length === 0 && (
            <div className="bg-white pop-art-border pop-art-shadow p-8 min-h-[600px] flex flex-col items-center justify-center">
              {!previewUrl ? (
                <div className="text-center space-y-8 animate-pop">
                  <div className="bg-[#00ffff] pop-art-border p-12 rounded-full inline-block shadow-2xl border-black">
                    <i className="fas fa-camera text-8xl text-black"></i>
                  </div>
                  <h3 className="text-6xl font-comic uppercase tracking-tighter text-black">FEED ME A PHOTO!</h3>
                  <p className="font-comic text-2xl text-black/50 uppercase italic">Get 3 different variations in one go!</p>
                </div>
              ) : (
                <div className="w-full flex flex-col items-center gap-8 animate-pop">
                  <div className="flex items-center justify-between w-full border-b-4 border-black pb-4">
                    <h3 className="text-4xl font-comic uppercase text-[#ff00ff] italic">READY TO TRANSFORM!</h3>
                    <button onClick={() => { setPreviewUrl(null); setFile(null); }} className="font-comic text-xl text-black bg-[#ffde03] px-4 py-1 pop-art-border-sm hover:scale-110">RESET</button>
                  </div>
                  <div className="pop-art-border pop-art-shadow-sm bg-black p-2 max-w-lg">
                    <img src={previewUrl} className="w-full h-auto grayscale hover:grayscale-0 transition-all duration-700" />
                  </div>
                </div>
              )}
            </div>
          )}

          {results.length > 0 && !loading && (
            <div className="space-y-12 animate-pop pb-12">
              <div className="text-center md:text-left flex flex-col md:flex-row items-baseline gap-4">
                <h3 className="text-6xl md:text-8xl font-comic uppercase tracking-tighter text-black italic leading-none">
                   <span className="bg-[#00ffff] text-black px-4 mr-3 pop-art-border shadow-lg inline-block">BOOM!</span>
                   3X VIBES
                </h3>
                <p className="font-comic text-2xl text-[#ff00ff] uppercase italic">Pick your favorite or take them all!</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {results.map((res, idx) => (
                  <div key={idx} className="flex flex-col gap-4 animate-pop" style={{ animationDelay: `${idx * 0.1}s` }}>
                    <div className="bg-white pop-art-border pop-art-shadow-sm p-4 group relative">
                       <div className="absolute -top-3 -right-3 bg-black text-white font-comic px-4 py-1 z-10 border-2 border-[#00ffff] rotate-6">
                         V.{idx + 1}
                       </div>
                       <div className="bg-black p-1 overflow-hidden">
                          <img src={res.imageUrl} className="w-full h-auto block transform group-hover:scale-[1.03] transition-transform duration-700" alt={`Variation ${idx + 1}`} />
                       </div>
                    </div>
                    <button 
                      onClick={() => handleDownload(res.imageUrl, idx)} 
                      className="w-full bg-[#39ff14] text-black pop-art-border-sm py-4 font-comic text-2xl uppercase hover:bg-black hover:text-[#39ff14] transition-all shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] active:translate-x-1 active:translate-y-1 active:shadow-none"
                    >
                       <i className="fas fa-download mr-2"></i> DOWNLOAD V.{idx + 1}
                    </button>
                  </div>
                ))}
              </div>

              <div className="bg-[#ff00ff] text-white pop-art-border p-6 pop-art-shadow-sm flex items-center gap-6 mt-12">
                 <div className="bg-black text-[#00ffff] w-12 h-12 flex items-center justify-center pop-art-border rounded-full rotate-12 flex-shrink-0">
                    <i className="fas fa-heart text-xl"></i>
                 </div>
                 <p className="font-comic text-xl text-black">
                   Tag us <a href="https://www.instagram.com/art_of_timeline/" className="underline font-black hover:text-white">@art_of_timeline</a> with your favorites!
                 </p>
              </div>
            </div>
          )}
        </section>
      </div>
    </Layout>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { PopArtConfig } from "../types";

export const transformToPopArt = async (
  base64Image: string,
  mimeType: string,
  config: PopArtConfig,
  variationIndex: number = 1
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Add variation specifics to ensure 3 different looks
  let variationTweak = '';
  if (variationIndex === 1) {
    variationTweak = "Focus on a bright, high-energy background with dynamic sunburst rays and primary pop-art colors.";
  } else if (variationIndex === 2) {
    variationTweak = "Emphasize cool neon tones, intricate halftone dot patterns, and sharp, geometric background shapes.";
    // For variation 2, maybe swap some colors
  } else {
    variationTweak = "Use an explosive action-oriented background with comic speed lines and a slightly different secondary color palette.";
  }

  let styleSpecifics = '';
  switch (config.mood) {
    case 'Cartoonish Pop Art':
      styleSpecifics = `- Style: Playful 2D cartoon/animation aesthetic. Round thick outlines, bubbly colors.`;
      break;
    case 'Futuristic Pop':
      styleSpecifics = `- Style: Hyper-Neon, glowing holographic textures, neon halos.`;
      break;
    case 'Synthwave Glow':
      styleSpecifics = `- Style: 80s radical aesthetics, pinks, purples, blues, retro sunset background.`;
      break;
    case 'Graffiti Urban':
      styleSpecifics = `- Style: Gritty street art, paint drips, explosive marker splatters.`;
      break;
    case 'Manga Noir':
      styleSpecifics = `- Style: High-contrast black and white, sharp screen-tones.`;
      break;
    case 'Anime Inspired':
      styleSpecifics = `- Style: Shonen anime cel-shading, dynamic energy particles, vivid lighting.`;
      break;
    default:
      styleSpecifics = `- Style: Classic bold Pop-Art colors with halftone dots.`;
  }

  const prompt = `
    TASK: Transform this photo into a ${config.mood} masterpiece. (Variation ${variationIndex})
    ${styleSpecifics}

    VARIATION UNIQUE TWEAK: ${variationTweak}

    AUTO-DETECTION RULES:
    1. If no names are provided, analyze the environment and subjects. 
       - If there are people, invent a catchy duo/solo alias (e.g., "TEAM DYNAMIC", "THE HERO", "VIBE MASTER").
       - If it's a scene, use an environment-specific title (e.g., "STREET VIBES", "CITY PULSE").
    2. If no caption is provided, add a contextually relevant comic-style sound effect or phrase (e.g., "ZAP!", "BOOM!", "STYLISH!", "POW!") in a stylized bubble.

    PROVIDED TEXT:
    - Names/Title: "${config.coupleName || 'DETECT AUTOMATICALLY'}"
    - Caption/Word: "${config.customText || 'DETECT AUTOMATICALLY'}"

    CORE CONSTRAINTS:
    - Maintain 100% facial likeness. DO NOT replace the person's identity.
    - Colors must be EXTREMELY SATURATED and VIBRANT.
    - Use thick black outlines and halftone dots.
    - Background must be an abstract, energetic pop-art burst.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1] || base64Image,
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    let generatedImageUrl = '';
    if (response.candidates && response.candidates[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          generatedImageUrl = `data:image/png;base64,${part.inlineData.data}`;
          break;
        }
      }
    }

    if (!generatedImageUrl) throw new Error("Processing failed.");
    return generatedImageUrl;
  } catch (error: any) {
    throw new Error(error.message || "Failed to generate art.");
  }
};

